<?php
declare(strict_types=1);namespace App\Models;
use App\Core\Database;
final class AuthModel {public function byEmail(string $email):?array{$q=Database::connection()->prepare("SELECT u.* FROM users u WHERE u.email=? AND u.status='active' LIMIT 1");$q->execute([$email]);return $q->fetch()?:null;}public function permissions(int $id):array{$q=Database::connection()->prepare('SELECT DISTINCT p.permission_key FROM permissions p JOIN role_permissions rp ON rp.permission_id=p.id JOIN user_roles ur ON ur.role_id=rp.role_id WHERE ur.user_id=?');$q->execute([$id]);return array_column($q->fetchAll(),'permission_key');}public function roles(int $id):array{$q=Database::connection()->prepare('SELECT r.role_key FROM roles r JOIN user_roles ur ON ur.role_id=r.id WHERE ur.user_id=?');$q->execute([$id]);return array_column($q->fetchAll(),'role_key');}}
